// Clasificador de juguete: elige una de las R para cada aplicación de un inventario INVENTADO.
// Los umbrales de «zombi» e «inactiva» salen de la guía de AWS leída el 16-11-2026; el resto de las reglas son un criterio simplificado mío.
function clasificar(a) {
  if (a.dias_sin_conexiones >= 90 || a.cpuMemProm < 5) return 'Retire (apagar: aplicación zombi)';
  if (a.cpuMemProm <= 20 && a.dias_observados >= 90) return 'Retire o Retain (inactiva: revisar con su dueño)';
  if (a.datosDebenQuedarEnElPais) return 'Retain (requisito de residencia de datos)';
  if (a.hardwareEspecial) return 'Retain (depende de hardware sin equivalente en la nube)';
  if (a.existeSaaS) return 'Repurchase (reemplazar por un producto SaaS)';
  if (a.necesitaEscalarYCambiar) return 'Refactor (rediseñar con funciones nativas; es lo más caro)';
  if (a.baseDeDatosPropia) return 'Replatform (mover la base a un servicio administrado)';
  return 'Rehost (lift and shift: mover sin cambios)';
}
const inventario = [
  { n: 'sistema de turnos de la balanza (2009)', cpuMemProm: 2, dias_sin_conexiones: 120, dias_observados: 120 },
  { n: 'intranet de RR. HH.', cpuMemProm: 35, existeSaaS: true, dias_sin_conexiones: 0, dias_observados: 120 },
  { n: 'control de la cinta clasificadora', cpuMemProm: 40, hardwareEspecial: true, dias_sin_conexiones: 0, dias_observados: 120 },
  { n: 'seguimiento de envíos (monolito)', cpuMemProm: 55, necesitaEscalarYCambiar: true, dias_sin_conexiones: 0, dias_observados: 120 },
  { n: 'facturación con base propia', cpuMemProm: 45, baseDeDatosPropia: true, dias_sin_conexiones: 0, dias_observados: 120 },
  { n: 'portal de clientes', cpuMemProm: 50, dias_sin_conexiones: 0, dias_observados: 120 },
  { n: 'registro de choferes', cpuMemProm: 30, datosDebenQuedarEnElPais: true, dias_sin_conexiones: 0, dias_observados: 120 },
];
const cuenta = {};
for (const a of inventario) {
  const r = clasificar(a);
  console.log(a.n.padEnd(42), '->', r);
  const clave = r.split(' ')[0]; cuenta[clave] = (cuenta[clave] ?? 0) + 1;
}
console.log(cuenta);

// TODOS LOS PRECIOS SON INVENTADOS para ilustrar el método; no son precios de lista de ningún proveedor.
const H = 730;                                   // horas por mes (aprox.)
const nube = { usdPorVcpuHora: 0.05, extra: 0.30 }; // +30 % por base de datos administrada, red y soporte (supuesto)
const propio = {
  servidor: { vcpu: 64, usd: 18000, vidaMeses: 60 }, // compra amortizada a 5 años
  coloMes: 250,        // por servidor: espacio, energía y red en un centro de datos alquilado
  personalMes: 4000,   // parte del tiempo de quien opera (supuesto)
  migracion: 30000,    // proyecto de mudanza, una sola vez
  holgura: 1.5,        // capacidad extra sobre el pico
};
const costoNube = (prom) => prom * H * nube.usdPorVcpuHora * (1 + nube.extra);
function costoPropio(pico) {
  const n = Math.ceil((pico * propio.holgura) / propio.servidor.vcpu);
  return n * (propio.servidor.usd / propio.servidor.vidaMeses + propio.coloMes) + propio.personalMes;
}
// la nube cobra lo que usás (el promedio); lo propio se compra para el pico
console.log('vCPU prom. | nube | propio si pico = 1,5 x prom. | propio si pico = 6 x prom.');
for (const prom of [20, 50, 100, 200, 400, 800]) {
  const f = (v) => ('USD ' + v.toFixed(0)).padStart(10);
  console.log(String(prom).padStart(10), '|', f(costoNube(prom)), '|', f(costoPropio(prom * 1.5)).padStart(27), '|', f(costoPropio(prom * 6)).padStart(27));
}
function cruce(razon) { for (let p = 5; p < 5000; p += 5) if (costoPropio(p * razon) < costoNube(p)) return p; return null; }
console.log('Promedio desde el cual lo propio sale más barato: pico 1,5x ->', (cruce(1.5) ?? 'ninguno'), 'vCPU; pico 6x ->', (cruce(6) ?? 'ninguno'));
const p = 800, ahorro = costoNube(p) - costoPropio(p * 1.5);
console.log(`Con ${p} vCPU y pico 1,5x: ahorro USD ${ahorro.toFixed(0)}/mes; la mudanza se paga en ${(propio.migracion / ahorro).toFixed(1)} meses (sin contar los meses con ambos entornos).`);
